//
// Relay-added SwiftPM manifest for the vendored melonDS tree (upstream builds
// with CMake). The source list is upstream's `src/CMakeLists.txt` core target
// with the options Relay does not ship left out: no JIT (ENABLE_JIT=OFF: the
// App Store forbids it and the interpreter is what runs everywhere), no OpenGL
// renderer (software rendering only), no GDB stub, no frontend. teakra (MIT,
// the DSi DSP) is compiled as upstream links it. RelayBridge/ is Relay's own
// Platform implementation and C API (GPL-3.0-or-later, see RelayBridge/README.md).
import PackageDescription

let package = Package(
    name: "melonDS",
    platforms: [
        .iOS(.v17),
        .tvOS(.v17),
        .macOS(.v14),
    ],
    products: [
        .library(name: "MelonRelay", targets: ["MelonRelay"]),
    ],
    targets: [
        .target(
            name: "MelonRelay",
            path: ".",
            sources: [
                "src/ARCodeFile.cpp",
