                "src/GPU3D_Texcache.cpp",
                "src/Mic.cpp",
                "src/NDS.cpp",
                "src/NDSCart.cpp",
                "src/ROMList.cpp",
                "src/FreeBIOS.cpp",
                "src/RTC.cpp",
                "src/Savestate.cpp",
                "src/SPI.cpp",
                "src/SPI_Firmware.cpp",
                "src/SPU.cpp",
